/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'fs'
import { ElectionParser } from './parser.js'
import { VotingEngine } from './engine.js'

// Parse arguments
if (process.argv.length !== 3) {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

const mode = process.argv[2]
if (mode !== 'rounds' && mode !== 'tally') {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf-8')
} catch (e) {
  process.stderr.write('error: failed to read stdin\n')
  process.exit(2)
}

// Parse election
const parser = new ElectionParser()
try {
  const election = parser.parse(input)

  // Run voting
  const engine = new VotingEngine(election)
  const results = engine.runElection()

  // Output results
  if (mode === 'rounds') {
    for (const round of results.rounds) {
      process.stdout.write(formatRound(round))
    }
  } else if (mode === 'tally') {
    process.stdout.write(`rounds ${results.rounds.length}\n`)
  }

  if (results.winner) {
    process.stdout.write(`winner ${results.winner}\n`)
  } else {
    process.stdout.write('no winner\n')
  }

  process.exit(0)
} catch (error) {
  process.stderr.write(error.message + '\n')
  process.exit(2)
}

function formatRound(round) {
  const candidates = Array.from(round.votes.entries())
    .sort(([nameA, votesA], [nameB, votesB]) => {
      if (votesB !== votesA) return votesB - votesA
      return nameA.localeCompare(nameB)
    })

  const votes = candidates.map(([name, count]) => `${name}=${count}`).join(' ')
  let output = `round ${round.number}: ${votes} exhausted=${round.exhausted}\n`

  if (round.eliminated) {
    output += `eliminated ${round.eliminated}\n`
  }

  return output
}
"}

