 * Parser for election input format.
 * Handles candidates declaration and ballots.
 */

export class ElectionParser {
  parse(input) {
    const lines = input.split('\n')
    // Remove trailing empty string from trailing newline
    if (lines.length > 0 && lines[lines.length - 1] === '') {
      lines.pop()
    }

    const election = {
      candidates: [],
      ballots: []
    }

    let candidatesDeclared = false
    let lineNumber = 0

    for (const rawLine of lines) {
      lineNumber++

      // Trim and skip empty lines and comments
      const line = rawLine.trim()
      if (line === '' || line.startsWith('#')) {
        continue
      }

      // Split on whitespace
      const tokens = line.split(/\s+/)
      if (tokens.length === 0) {
        continue
      }

      const directive = tokens[0]

      if (directive === 'candidates') {
        if (candidatesDeclared) {
          throw new Error(`error: line ${lineNumber}: candidates must be declared once, before any ballot`)
        }

        if (tokens.length < 2) {
          throw new Error(`error: line ${lineNumber}: expected candidates <name>...`)
        }

        const names = tokens.slice(1)
        const seen = new Set()

        for (const name of names) {
          if (!this.isValidName(name)) {
            throw new Error(`error: line ${lineNumber}: invalid candidate name ${name}`)
          }
          if (seen.has(name)) {
            throw new Error(`error: line ${lineNumber}: candidate ${name} is declared twice`)
          }
          seen.add(name)
        }

        election.candidates = names
        candidatesDeclared = true
      } else if (directive === 'ballot') {
        if (!candidatesDeclared) {
          throw new Error(`error: line ${lineNumber}: candidates must be declared once, before any ballot`)
        }

        if (tokens.length < 2) {
          throw new Error(`error: line ${lineNumber}: expected ballot <count> <candidate>...`)
        }

        // Parse count
        const countStr = tokens[1]
        if (!this.isValidCount(countStr)) {
          throw new Error(`error: line ${lineNumber}: count must be a positive integer`)
        }
        const count = parseInt(countStr, 10)

        // Parse candidate names
        const names = tokens.slice(2)
        if (names.length === 0) {
          throw new Error(`error: line ${lineNumber}: expected ballot <count> <candidate>...`)
        }

        const candidateSet = new Set(election.candidates)
        const seen = new Set()

        for (const name of names) {
          if (!candidateSet.has(name)) {
            throw new Error(`error: line ${lineNumber}: unknown candidate ${name}`)
          }
          if (seen.has(name)) {
            throw new Error(`error: line ${lineNumber}: candidate ${name} is repeated`)
          }
          seen.add(name)
        }

        election.ballots.push({ count, choices: names })
      } else {
        throw new Error(`error: line ${lineNumber}: unknown directive ${directive}`)
      }
    }

    // Check that candidates were declared
    if (!candidatesDeclared) {
      throw new Error('error: no candidates')
    }

    return election
  }

  isValidName(name) {
    return /^[A-Za-z0-9_-]+$/.test(name)
  }

  isValidCount(str) {
    // Must be a positive integer without sign or leading zero
    if (str === '' || str[0] === '0' && str.length > 1) {
      return false
    }
    if (/^[1-9]\d*$/.test(str)) {
      return true
    }
    return false
  }
}
"}

